def countBits(n):
    count = 0
    while n:
        n &= n - 1  # Clear lowest set bit
        count += 1
    return count  # O(number of set bits)

def singleNumber(nums):
    result = 0
    for num in nums:
        result ^= num  # Pairs cancel out
    return result  # O(n)

def subsets(nums):
    n = len(nums)
    result = []

    for mask in range(1 << n):  # 0 to 2^n - 1
        subset = []
        for i in range(n):
            if (mask >> i) & 1:  # Check if bit i is set
                subset.append(nums[i])
        result.append(subset)

    return result  # O(2^n * n)
